      END IF;
    ELSIF TG_OP = 'UPDATE' AND NEW.credits IS DISTINCT FROM OLD.credits THEN
      RAISE EXCEPTION 'client role cannot update profile credits'
        USING ERRCODE = '42501';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;
